  function getCurrentSixAspectSpec() {
    const wf = (game && game.weaponForm) || "sword";
    const pos = (arena && arena.weaponPosture === "xuanzhong") ? "xuanzhong" : "qinglian";
    return SIX_ASPECT_SPECS[`${wf}_${pos}`] || SIX_ASPECT_SPECS.sword_qinglian;
  }

